package main

import (
	"reflect"
	"testing"
)

func TestClassicRules(t *testing.T) {
	rules := []Rule{{3, "Fizz"}, {5, "Buzz"}}
	got := FizzBuzz(15, rules)
	want := []string{"1", "2", "Fizz", "4", "Buzz",
		"Fizz", "7", "8", "Fizz", "Buzz",
		"11", "Fizz", "13", "14", "FizzBuzz"}
	if !reflect.DeepEqual(got, want) {
		t.Errorf("got %v, want %v", got, want)
	}
}

func TestSingleNumber(t *testing.T) {
	got := FizzBuzz(1, []Rule{{3, "Fizz"}})
	want := []string{"1"}
	if !reflect.DeepEqual(got, want) {
		t.Errorf("got %v, want %v", got, want)
	}
}

func TestNoRules(t *testing.T) {
	// 没有规则时全输出数字
	got := FizzBuzz(5, []Rule{})
	want := []string{"1", "2", "3", "4", "5"}
	if !reflect.DeepEqual(got, want) {
		t.Errorf("got %v, want %v", got, want)
	}
}

func TestCustomRules(t *testing.T) {
	// 自定义规则：2->"Go", 7->"Lang"
	rules := []Rule{{2, "Go"}, {7, "Lang"}}
	got := FizzBuzz(14, rules)
	// 14 同时被 2 和 7 整除 -> "GoLang"
	if got[13] != "GoLang" {
		t.Errorf("14 should be GoLang, got %s", got[13])
	}
	if got[1] != "Go" {
		t.Errorf("2 should be Go, got %s", got[1])
	}
}

func TestThreeRules(t *testing.T) {
	// 三条规则：2->"A", 3->"B", 5->"C"
	rules := []Rule{{2, "A"}, {3, "B"}, {5, "C"}}
	got := FizzBuzz(6, rules)
	// 6 被 2 和 3 整除 -> "AB"
	if got[5] != "AB" {
		t.Errorf("6 should be AB, got %s", got[5])
	}
}
